            {
              "note_id": "FCT_0091",
              "exact_quote": "byte, which takes one byte of memory, and in one byte we can store values from -128 to 127."
            },
            {
              "note_id": "FCT_0091",
              "exact_quote": "short which takes 2 bytes and with this we can store values up to 32,000."
            },
            {
              "note_id": "FCT_0091",
              "exact_quote": "integer, which we have seen before, integers take 4 bytes of memory and allow us to store values up to 2 billion."
            },
            {
              "note_id": "FCT_0091",
              "exact_quote": "long which takes 8 bytes, and with this we can store even larger numbers."
            },
            {
              "note_id": "FCT_0093",
              "exact_quote": "If you want to store a number that has a decimal point, you have to use float or double."
            },
            {
              "note_id": "FCT_0094",
              "exact_quote": "Float occupies 4 bytes and double occupies 8 bytes."
            },
            {
              "note_id": "FCT_0095",
              "exact_quote": "Double can store larger numbers than float."
            },
            {
              "note_id": "FCT_0096",
              "exact_quote": "Char stores a single character and takes 2 bytes, supporting international letters."
            },
            {
              "note_id": "FCT_0097",
              "exact_quote": "Boolean stores true/false values."
            },
            {
              "note_id": "FCT_0098",
              "exact_quote": "An integer occupies 4 bytes and can store values up to about 2 billion."
            },
            {
              "note_id": "FCT_0099",
              "exact_quote": "A byte occupies 1 byte and can store values up to 127."
            }
          ],
